  setPauseRecording(val) {
    if (val == "recording") {
      if (this.mediaRecorder) {
        this.mediaRecorder.pause();
      };
    } else if (val == "paused") {
      if (this.mediaRecorder) {
        this.mediaRecorder.resume();
      };
    };
  };

  handleRecordStart() {
    if (this.state.micOn == false) {
      this.setState({
        playingAt: 0.0,
        incPitch: 1
      });
      this.masterGainNode[0]?.context?.close();
      this.masterGainNode = [];
      const context = new (window.AudioContext || window.webkitAudioContext)();
      const current_time = context.currentTime;
      this.context = context;
      this.state.audioBuff.forEach((buf, i) => {
        var source = context.createBufferSource();
        this.mixedSource = source;
        source.buffer = buf;
        const masterGainNode = context.createGain();
        this.masterGainNode.push(masterGainNode);
        masterGainNode.gain.value = this.state?.masterGain / 100;
        this.audio_source.push(source);
        source.playbackRate.value = 1;
        source.connect(this.masterGainNode[i]);
        if (masterGainNode) {
          masterGainNode.connect(context.destination);
          if ((i = this.state.audioBuff.length - 1)) {
            source.start(0);
            this.videoRef.current.play();
            this.videoRef.current.muted = true;
            if (this.state.music_volume_handle != 0) {
              this.volumeHandleOnload();
            };
          };
          source.onended = function (e) {
            this.mixedSource = null;
            this.setState({ playButtonNextAction: "Resume" });
            // if (this.state.isRepeat) {
            //   setTimeout(() => {
            //     this.onHandleRepeatSong();
            //   }, 2000);
            // };
          }.bind(this);
          this.setState({
            playButtonNextAction: "Pause",
            isPlaying: true,
            time: false,
          });
        };
        var interval = setInterval(() => {
          this.setState({
            playingAt:
              this.masterGainNode[i]?.context?.currentTime *
              this.state.incPitch,
          });
          if (this.state.playingAt > this.inputAudio[i]?.data?.duration) {
            this.setState({ playButtonNextAction: "Play" });
            clearInterval(interval);
            this.mediaRecorder.stop();
            this.setState({
              micOn: false,
              recordingOn: false,
            });
          } else if (this.state.time === true) {
            clearInterval(interval);
          };
        }, 1000);
      });
      this.setMedioRecorderOff();
    };
  };

  handleCancelRecording() {
    if (this.mediaRecorder) {
      this.mediaRecorder.stop();
      this.setState({
        isCancelRecording: true,
        micOn: false,
        recordingOn: false,
      });
    };
  };

  setMedioRecorderOff() {
    this.setState({
      micOn: true,
      recordingOn: true,
    });
    if (this.state?.selectedAudioDevice) {
      this.setState({
        isRecording: true,
      });
      const audio = this.state?.selectedAudioDevice?.length > 0 ? { deviceId: null } : true;
      navigator.mediaDevices
        .getUserMedia({ audio: true, video: false })
        .then((stream) => {
          const options = { mimeType: "audio/webm" };
          this.mediaRecorder = new MediaRecorder(stream, options);
          this.setState({
            record_start_stop: new MediaRecorder(stream, options),
          });
          this.mediaRecorder.addEventListener("dataavailable", (e) => {
            this.state.recordedChunksData.push(e.data);
          });
          this.mediaRecorder.addEventListener("pause", (e) => {
          });
          this.mediaRecorder.addEventListener("resume", (e) => {
          });
          this.mediaRecorder.addEventListener("stop", () => {
            if (this.state.isCancelRecording) {
            } else {
              this.setState({
                isUploadLoader: true,
              });
              const val1 = window.location.search;
              const daata1 = val1.split("=");
              const user_id = daata1[3].split("?");
              const blob = new Blob(this.state.recordedChunksData, {
                type: "audio/mp3",
              });
              var formData = new FormData();
              const fileName = `${this?.state?.song_name}.mp3`;
              const audioBlob = new Blob(this.state.recordedChunksData, {
                type: "audio/mp3",
              });
              const file = new File([audioBlob], fileName, {
                type: "audio/mp3",
              });
              formData.append("file", file);
              formData.append("user_id", `${user_id[0]}`);
              formData.append("song_id", `${this.state.audio_song_id}`);
              axios({
                method: "post",
                url: "https://159.223.251.167:3000/uploadSong",
                // url: "http://192.168.1.20:3000/uploadSong",
                data: formData,
              })
                .then((res) => {
                  this.setState({
                    isUploadLoader: false,
                  });
                  if (res?.data?.success == false) {
                    // MESSAGE.error(res?.data?.message, 2)
                  } else {
                    this.getSongById();
                    MESSAGE.success("Recorded Successfully.", 2);
                  };
                })
                .catch((err) => {
                  this.setState({
                    isUploadLoader: false,
                  });
                });
              // end of the upload song
            };
            stream.getTracks().forEach((track) => {
              track.stop();
            });
          });
          this.mediaRecorder.start();
        });
    };
  };

  handleClickStopRecord() {
    this.setState({
      isRecording: false,
      micOn: false,
    });
    if (this.mediaRecorder) {
      this.mediaRecorder.stop();
      this.setState({
        recordingOn: false,
      });
    };
  };

  handlePermissionState() {
    navigator.permissions.query({ name: "microphone" }).then((queryResults) => {
      this.setState({
        microphonePermissionState: queryResults?.state,
      });
      this.getAvailableAudioDevices().then((devices) => {
        this.setState({
          availableDevices: devices,
          selectedAudioDevice: devices.find((device) => device.id === "default")
            ?.id,
        });
      });
      queryResults.onChange = function (onChangeResult) {
        if (onChangeResult.target) {
          this.microphonePermissionState = onChangeResult?.target?.state;
        };
      };
    });
  };

  getAvailableAudioDevices() {
    return new Promise((resolve) => {
      navigator.mediaDevices.enumerateDevices().then((devices) => {
        const availableDevices = devices
          ?.filter((d) => d?.kind === "audiooutput")
          .map((d) => {
            return { id: d.deviceId, name: d.label };
          });
        resolve(availableDevices);
      });
    });
  };

