  onClickNextButton() {
    this.setState({
      onPlay: true,
    });
    switch (this.state.playButtonNextAction) {
      case "Play":
        this.masterGainNode[0]?.context?.close();
        this.masterGainNode = [];
        const context = new (window.AudioContext ||
          window.webkitAudioContext)();
        const current_time = context.currentTime;
        this.context = context;
        this.state.audioBuff.forEach((buf, i) => {
          var source = context.createBufferSource();
          this.mixedSource = source;
          source.buffer = buf;
          const masterGainNode = context.createGain();
          this.masterGainNode.push(masterGainNode);
          masterGainNode.gain.value = this.state?.masterGain / 100;
          this.audio_source.push(source);
          source.playbackRate.value = this.state.incPitch;
          source.connect(this.masterGainNode[i]);
          if (masterGainNode) {
            masterGainNode.connect(context.destination);
            if ((i = this.state.audioBuff.length - 1)) {
              source.start(0);
              this.videoRef.current.play();
              this.videoRef.current.muted = true;
              if (this.state.music_volume_handle != 0) {
                this.volumeHandleOnload();
              }
            }
            source.onended = function (e) {
              this.mixedSource = null;
              this.setState({ playButtonNextAction: "Resume" });
              if (this.state.isRepeat) {
                setTimeout(() => {
                  this.onHandleRepeatSong();
                }, 2000);
              };
            }.bind(this);
            this.setState({
              playButtonNextAction: "Pause",
              isPlaying: true,
              time: false,
            });
          }
          var interval = setInterval(() => {
            this.setState({
              playingAt:
                this.masterGainNode[i]?.context?.currentTime *
                this.state.incPitch,
            });
            if (this.state.playingAt > this.inputAudio[i]?.data?.duration) {
              this.setState({ playButtonNextAction: "Resume" });
              clearInterval(interval);
            } else if (this.state.time === true) {
              clearInterval(interval);
            }
          }, 1000);
        });
        break;
      case "Resume":
        if (this.inputAudio.length === 0) break;
        for (var i = 0; i < this.masterGainNode.length; i++) {
          this.masterGainNode[i].context?.resume();
        }
        this?.state?.recordingOn == true && this.setPauseRecording("paused");
        this.videoRef.current.play();
        this.videoRef.current.muted = true;
        this.setState({
          playButtonNextAction: "Pause",
          isPlaying: true,
        });
        break;
      case "Pause":
        for (var i = 0; i < this.masterGainNode.length; i++) {
          this.masterGainNode[i]?.context?.suspend(
            this.masterGainNode[i].context.destination
          );
        }
        this?.state?.recordingOn == true && this.setPauseRecording("recording");
        this.videoRef.current.pause();
        this.setState({
          loop: false,
          playButtonNextAction: "Resume",
          isPlaying: false,
        });
        break;
      default:
        console.log("default", this.state.playButtonNextAction);
    }
    return;
  };

